<?php
namespace Tests;
use App\Services\{SalonStore,Tenant,Availability,Subscriptions,AutomaticInvoices,Notifications,PaidFeatures};
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Http,Crypt};
use Carbon\CarbonImmutable as Time;
final class PremiumBusinessTest extends TestCase{
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();Artisan::call('migrate',['--force'=>true]);foreach(['salon_state','providers','platform_payments','deliveries','guest_accounts','calendar_tasks','calendar_connections'] as $t)DB::table($t)->delete();$s=SalonStore::initial();$s['settings']['businessMode']='team';$s['subscription']=['status'=>'active','plan'=>'pro','calendarLimit'=>2,'trialStartedAt'=>'2030-01-01T00:00:00Z','trialEndsAt'=>'2030-03-01T00:00:00Z','paidUntil'=>'2030-04-01T00:00:00Z'];DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode($s)]);Time::setTestNow('2030-03-15T10:00:00Z');config(['plans.pro_price'=>6000,'integrations.path'=>storage_path('framework/premium-test.enc')]);$this->withSession(['admin'=>true,'provider_id'=>1,'_token'=>str_repeat('p',40)])->withHeader('X-CSRF-TOKEN',str_repeat('p',40));Http::preventStrayRequests();}
 protected function tearDown():void{Time::setTestNow();foreach(glob(storage_path('framework/premium-test.enc*')) as $p)unlink($p);parent::tearDown();}
 private function requestId():string{return (string)\Illuminate\Support\Str::uuid();}
 public function test_basic_plan_cannot_enable_pro_features_and_cannot_forge_calendar_access():void{app(SalonStore::class)->mutate(function(&$s){$s['subscription']['plan']='basic';});$this->putJson('/api/config',['settings'=>array_replace(app(SalonStore::class)->read()['settings'],['reminderGuest'=>true])])->assertStatus(402);$this->putJson('/api/config',['settings'=>array_replace(app(SalonStore::class)->read()['settings'],['autoInvoice'=>true])])->assertStatus(402);$this->postJson('/api/provider-members',['staff_id'=>'anna','email'=>'staff@example.com','password'=>'Staff-password-long','password_confirmation'=>'Staff-password-long'])->assertStatus(402);$this->postJson('/api/subscription/calendars',['requestId'=>$this->requestId(),'name'=>'Extra','acceptMonthlyFee'=>true])->assertStatus(402);}
 public function test_calendar_addon_is_idempotent_and_only_changes_future_monthly_prices():void{$s=app(SalonStore::class)->read();$before=count($s['staff']);$old=collect($s['subscription']['charges'])->firstWhere('kind','monthly');$id=$this->requestId();$payload=['requestId'=>$id,'name'=>'Extra calendar','acceptMonthlyFee'=>true];$this->postJson('/api/subscription/calendars',$payload)->assertOk()->assertJsonPath('status','complete');$this->postJson('/api/subscription/calendars',$payload)->assertOk();$s=app(SalonStore::class)->read();$this->assertCount($before+1,$s['staff']);$this->assertSame(1,$s['subscription']['extraCalendars']);$this->assertSame(8000,Subscriptions::monthlyAmount($s));$this->assertSame($old['amount'],collect($s['subscription']['charges'])->firstWhere('id',$old['id'])['amount']);Time::setTestNow('2030-04-02T10:00:00Z');$s=app(SalonStore::class)->read();$new=collect($s['subscription']['charges'])->first(fn($c)=>str_starts_with($c['from'],'2030-04-01'));$this->assertSame(8000,$new['amount']);}
 public function test_calendar_purchase_requires_consent_and_rejects_editor():void{$this->postJson('/api/subscription/calendars',['requestId'=>$this->requestId(),'name'=>'Extra','acceptMonthlyFee'=>false])->assertUnprocessable();$this->withSession(['admin'=>false]);$this->postJson('/api/subscription/calendars',['requestId'=>$this->requestId(),'name'=>'Extra','acceptMonthlyFee'=>true])->assertUnauthorized();}
 public function test_staff_weekly_hours_and_staff_date_exception_drive_validation_and_slots():void{$s=app(SalonStore::class)->read();$date='2035-03-12';$weekday=Time::parse($date)->dayOfWeekIso;$a=$s['availability'];$a['weeklyStaff']=[['staffId'=>'anna','weekday'=>$weekday,'closed'=>false,'openingTime'=>'09:15','closingTime'=>'11:15'],['staffId'=>'eszter','weekday'=>$weekday,'closed'=>true,'openingTime'=>'08:00','closingTime'=>'20:00']];$this->putJson('/api/availability',$a)->assertOk();$slots=$this->getJson('/api/slots?date='.$date.'&services=cut&staff=anna&public=1')->assertOk()->json();$this->assertNotEmpty($slots);$this->assertSame('09:15',$slots[0]['time']);foreach($slots as $slot)$this->assertGreaterThanOrEqual('09:15',$slot['time']);$this->getJson('/api/slots?date='.$date.'&services=massage&staff=eszter&public=1')->assertExactJson([]);$a['overrides']=[['date'=>$date,'staffId'=>'anna','closed'=>false,'openingTime'=>'12:00','closingTime'=>'14:00']];$this->putJson('/api/availability',$a)->assertOk();$s=app(SalonStore::class)->read();$this->assertSame([720,840],Availability::hours($s,$date,'anna'));$this->assertSame([null,null],Availability::hours($s,$date,'eszter'));$this->putJson('/api/availability',array_replace($a,['weeklyStaff'=>[['staffId'=>'foreign','weekday'=>1,'closed'=>false,'openingTime'=>'08:00','closingTime'=>'12:00']]]))->assertUnprocessable();}
 public function test_plan_change_keeps_previous_charges_and_is_idempotent():void{app(SalonStore::class)->mutate(function(&$s){$s['subscription']['plan']='basic';});$id=$this->requestId();$payload=['requestId'=>$id,'plan'=>'pro','acceptMonthlyFee'=>true];$this->postJson('/api/subscription/plan',$payload)->assertOk();$this->postJson('/api/subscription/plan',$payload)->assertOk();$s=app(SalonStore::class)->read();$this->assertTrue(PaidFeatures::enabled($s));$this->assertCount(1,$s['subscription']['planHistory']);$this->assertSame(4000,Subscriptions::monthlyAmount($s,'2030-03-01T00:00:00Z'));$this->assertSame(6000,Subscriptions::monthlyAmount($s,'2030-04-01T00:00:00Z'));}
 public function test_reminders_are_queued_once_and_not_sent_for_basic_plan():void{$s=app(SalonStore::class)->read();$s['settings']['reminderGuest']=true;$s['settings']['channel']='email';$b=['id'=>'reminder-test','updatedAt'=>now()->toISOString(),'staff'=>'anna','email'=>'guest@example.com','phone'=>'','status'=>'confirmed','start'=>now()->addDays(2)->toISOString()];app(Notifications::class)->enqueue($b,$s,'reminder');app(Notifications::class)->enqueue($b,$s,'reminder');$this->assertSame(1,DB::table('deliveries')->count());DB::table('deliveries')->delete();$s['subscription']['plan']='basic';app(Notifications::class)->enqueue($b,$s,'reminder');$this->assertSame(0,DB::table('deliveries')->count());}
 private function seedInvoice(bool $full=true,bool $buyer=true):void{app(\App\Services\Connections::class)->save(['billingo_key'=>'test-only-key','billingo_block'=>1]);app(SalonStore::class)->mutate(function(&$s)use($full,$buyer){$s['settings']['invoiceProvider']='billingo';$s['settings']['autoInvoice']=true;$s['bookings'][]=['id'=>'automatic-booking','name'=>'Invoice Guest','email'=>'invoice@example.com','phone'=>'06301234567','staff'=>'anna','start'=>'2030-03-10T10:00:00Z','services'=>['cut'],'status'=>'confirmed','serviceSnapshot'=>[['id'=>'cut','name'=>'Cut','price'=>8500,'duration'=>45]]];$p=['id'=>'automatic-payment','bookingId'=>'automatic-booking','status'=>'paid','method'=>'cash','amount'=>$full?8500:4000];if($buyer)$p['buyer']=['name'=>'Invoice Guest','country'=>'HU','zip'=>'1111','city'=>'Budapest','address'=>'Test Street 1','email'=>'invoice@example.com'];$s['payments'][]=$p;});}
 public function test_automatic_invoice_only_runs_once_for_a_fully_paid_booking():void{$this->seedInvoice();Http::fake(['api.billingo.hu/v3/partners'=>Http::response(['id'=>1]),'api.billingo.hu/v3/documents'=>Http::response(['id'=>10,'invoice_number'=>'TEST-10'])]);$result=app(AutomaticInvoices::class)->run();$this->assertSame(1,$result['issued']);app(AutomaticInvoices::class)->run();Http::assertSentCount(2);$this->assertSame('issued',app(SalonStore::class)->read()['invoiceRequests'][0]['status']);}
 public function test_missing_buyer_or_partial_payment_never_calls_an_external_invoicer():void{$this->seedInvoice(true,false);$result=app(AutomaticInvoices::class)->run();$this->assertSame(1,$result['waiting']);Http::assertNothingSent();$this->assertNotEmpty(app(SalonStore::class)->read()['autoInvoiceIssues']);app(SalonStore::class)->mutate(function(&$s){$s['payments'][0]['amount']=4000;unset($s['autoInvoiceAttempts']);});$this->assertSame(0,app(AutomaticInvoices::class)->run()['issued']);Http::assertNothingSent();}
 public function test_uncertain_invoice_is_never_reissued_automatically():void{$this->seedInvoice();Http::fake(['api.billingo.hu/v3/partners'=>Http::response(['id'=>1]),'api.billingo.hu/v3/documents'=>Http::response([],500)]);app(AutomaticInvoices::class)->run();Time::setTestNow('2030-03-15T12:00:00Z');app(AutomaticInvoices::class)->run();Http::assertSentCount(2);$this->assertSame('unknown',app(SalonStore::class)->read()['invoiceRequests'][0]['status']);}
 public function test_live_stripe_calendar_update_sets_recurring_amount_without_proration():void{config(['integrations.platform_stripe.key'=>'sk_test_only','integrations.platform_stripe.price'=>'price_base']);app(SalonStore::class)->mutate(function(&$s){$s['subscription']['id']='sub_test';});$until=Time::parse('2030-04-01T00:00:00Z')->timestamp;Http::fake(fn($r)=>$r->method()==='GET'?Http::response(['status'=>'active','current_period_end'=>$until,'items'=>['data'=>[['id'=>'base_item','quantity'=>1,'price'=>['id'=>'price_base','unit_amount'=>600000,'currency'=>'huf','product'=>'prod_test']]]]]):Http::response(['id'=>'sub_test']));$this->postJson('/api/subscription/calendars',['requestId'=>$this->requestId(),'name'=>'Stripe calendar','acceptMonthlyFee'=>true])->assertOk();Http::assertSent(fn($r)=>$r->method()==='POST'&&$r['proration_behavior']==='none'&&$r['items'][0]['price_data']['unit_amount']===200000&&$r['items'][0]['quantity']===1);$this->assertSame(1,app(SalonStore::class)->read()['subscription']['extraCalendars']);}

 public function test_stripe_timeout_can_be_reconciled_without_creating_a_second_calendar_or_charge():void{config(['integrations.platform_stripe.key'=>'sk_test_only','integrations.platform_stripe.price'=>'price_base']);app(SalonStore::class)->mutate(function(&$s){$s['subscription']['id']='sub_timeout';});$updated=false;$posts=0;$until=Time::parse('2030-04-01T00:00:00Z')->timestamp;Http::fake(function($r)use(&$updated,&$posts,$until){if($r->method()==='POST'){$updated=true;$posts++;throw new \Illuminate\Http\Client\ConnectionException('Simulated timeout');}$items=[['id'=>'base_item','quantity'=>1,'price'=>['id'=>'price_base','unit_amount'=>600000,'currency'=>'huf','product'=>'prod_test']]];if($updated)$items[]=['id'=>'addon_item','quantity'=>1,'price'=>['unit_amount'=>200000,'currency'=>'huf','product'=>'prod_test']];return Http::response(['status'=>'active','current_period_end'=>$until,'items'=>['data'=>$items]]);});$id=$this->requestId();$payload=['requestId'=>$id,'name'=>'Timeout calendar','acceptMonthlyFee'=>true];$before=count(app(SalonStore::class)->read()['staff']);$this->postJson('/api/subscription/calendars',$payload)->assertServerError();$this->assertCount($before,app(SalonStore::class)->read()['staff']);$this->postJson('/api/subscription/calendars',$payload)->assertOk();$this->assertSame(1,$posts);$this->assertCount($before+1,app(SalonStore::class)->read()['staff']);}
 public function test_upgraded_recurring_price_is_used_when_approving_a_bank_payment():void{app(SalonStore::class)->mutate(function(&$s){$s['subscription']['paidUntil']='2030-03-01T00:00:00Z';unset($s['subscription']['charges'],$s['subscription']['legacyPaidUntil']);});$charge=collect(app(SalonStore::class)->read()['subscription']['charges'])->firstWhere('kind','monthly');app(Subscriptions::class)->transfer(1,'bank-pro-test','2030-03-15',$charge['id']);$this->assertSame(6000,(int)DB::table('platform_payments')->where('reference','bank-pro-test')->value('amount'));}

 public function test_stripe_webhook_settles_pro_and_calendar_price_once():void{config(['integrations.platform_stripe.webhook_secret'=>'whsec_pro_test']);$s=SalonStore::initial();$s['subscription']=['id'=>'sub_pro_test','plan'=>'pro','status'=>'active','trialStartedAt'=>'2030-01-01T00:00:00Z','trialEndsAt'=>'2030-03-01T00:00:00Z','calendarAddons'=>[['quantity'=>1,'startsAt'=>'2030-03-01T00:00:00Z']]];DB::table('salon_state')->where('id',1)->update(['data'=>json_encode($s)]);$start=Time::parse('2030-03-01T00:00:00Z')->timestamp;$end=Time::parse('2030-04-01T00:00:00Z')->timestamp;$event=['id'=>'evt_pro_test','created'=>time(),'type'=>'invoice.paid','data'=>['object'=>['id'=>'in_pro_test','subscription'=>'sub_pro_test','customer'=>'cus_pro_test','paid'=>true,'currency'=>'huf','amount_paid'=>800000,'lines'=>['data'=>[['period'=>['start'=>$start,'end'=>$end]]]]]]];$body=json_encode($event);$t=time();$signature='t='.$t.',v1='.hash_hmac('sha256',$t.'.'.$body,'whsec_pro_test');for($i=0;$i<2;$i++)$this->call('POST','/api/platform-stripe/webhook',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_STRIPE_SIGNATURE'=>$signature],$body)->assertOk();$this->assertSame(1,DB::table('platform_payments')->count());$this->assertSame(8000,(int)DB::table('platform_payments')->value('amount'));$entry=collect(app(SalonStore::class)->read()['subscription']['charges'])->firstWhere('kind','monthly');$this->assertSame('paid',$entry['status']);}

}
